import React from 'react';
import ReactDOM from 'react-dom/client';
import {
  SideNav,
  SideNavHeader,
  SideNavItems,
  SideNavMenu,
  SideNavMenuItem,
  SideNavLink,
} from '@carbon/react';
import { Carbon20, Home20, DataReference16 } from '@carbon/icons-react';

function App() {
  return (
    <div style={{ display: 'flex', height: '100vh' }}>
      {/* SideNav in rail (collapsed) mode */}
      <SideNav isRail aria-label="Side navigation rail">
        <SideNavHeader prefix={<Carbon20 />} aria-label="Carbon">
          <h1 className="cds--side-nav__header">Carbon</h1>
        </SideNavHeader>
        <SideNavItems>
          {/* First drop-down menu */}
          <SideNavMenu title="Menu One" renderIcon={Home20} aria-label="Open Menu One">
            <SideNavMenuItem href="#">Option 1</SideNavMenuItem>
            <SideNavMenuItem href="#">Option 2</SideNavMenuItem>
            <SideNavMenuItem href="#">Option 3</SideNavMenuItem>
          </SideNavMenu>
          {/* Second drop-down menu */}
          <SideNavMenu title="Menu Two" renderIcon={DataReference16} aria-label="Open Menu Two">
            <SideNavMenuItem href="#">Item A</SideNavMenuItem>
            <SideNavMenuItem href="#">Item B</SideNavMenuItem>
          </SideNavMenu>
          {/* A regular link for contrast */}
          <SideNavLink renderIcon={Home20} href="#">
            Simple Link
          </SideNavLink>
        </SideNavItems>
      </SideNav>

      {/* Main content area to move pointer into */}
      <main style={{ flex: 1, padding: '1rem' }}>
        <h2>Main Content</h2>
        <p>
          Hover over the rail to expand it, open one of the menu dropdowns, then move
          your cursor here. Observe that the rail collapses but the menu panel
          remains open.
        </p>
      </main>
    </div>
  );
}

const root = ReactDOM.createRoot(document.getElementById('root'));
root.render(<App />);
